pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    // Prefer preserving a tight space for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size as f64 {
            score += 35.0;
        } else if post_residual == next_item_size as f64 {
            score -= 25.0;
        } else {
            let excess = (post_residual - next_item_size as f64) / bin_capacity as f64;
            score += 18.0 * excess.min(1.0);
        }
    } else {
        score -= 8.0 * progress;
    }

    // Reward bins whose remaining space is close to the observed average.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.12 * deviation;

    // Strongly discourage fragmentation near the end of the stream.
    if progress > 0.75 && post_residual < 20.0 {
        score += 15.0 * (progress - 0.75) / 0.25;
    }

    // A new bin is attractive only when existing bins are poor matches.
    if is_new_bin {
        score += 10.0;
        if open_bins_count > 0 {
            score += 0.03 * open_bins_count.min(20) as f64;
        }
    } else if fitting_bins_count <= 1 {
        // Preserve the final viable bin when alternatives are scarce.
        score -= 8.0;
    }

    // Slightly favor placing larger items now, reducing future pressure.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        1.0
    };

    if bin_residual == bin_capacity {
        score -= 12.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 9.0;
        } else {
            score += 7.0;
        }

        let exact_next = if post_residual == next_item_size { 1.0 } else { 0.0 };
        score -= 8.0 * exact_next;

        let capacity_gap = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
        let next_gap = next_item_size as f64 / bin_capacity as f64;
        score -= 5.0 * (capacity_gap - next_gap).max(0.0);
    } else {
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    let mean_gap = mean_residual - post_residual as f64;
    score -= 4.0 * (mean_gap / bin_capacity as f64).max(0.0);
    score += 2.0 * (post_residual as f64 / bin_capacity as f64);

    if post_residual < item_size {
        score += 1000.0;
    }

    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score += 1.5 * progress;
    }

    if open_bins_count > 1 {
        score -= 0.5 * (post_residual as f64 / bin_capacity as f64).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
